package cn.iocoder.yudao.module.amazon.controller.admin.listingsitems;
import cn.iocoder.yudao.framework.common.pojo.CommonResult; import cn.iocoder.yudao.module.amazon.controller.admin.listings.vo.*; import cn.iocoder.yudao.module.amazon.service.listingsitems.AmazonListingsItemsService; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.annotation.Resource; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.Map;
/** Amazon Listings Items 管理接口。 */
@Tag(name="管理后台 - Amazon Listings Items") @RestController @RequestMapping("/amazon/listings-items") public class AmazonListingsItemsController { @Resource private AmazonListingsItemsService service; @PostMapping("/search") @PreAuthorize("@ss.hasPermission('amazon:listings-items:query')") public CommonResult<Map<String,Object>> search(@Valid @RequestBody AmazonListingsSearchReqVO r){return CommonResult.success(service.search(r));} @PostMapping("/get") @PreAuthorize("@ss.hasPermission('amazon:listings-items:query')") public CommonResult<Map<String,Object>> get(@Valid @RequestBody AmazonListingsItemGetReqVO r){return CommonResult.success(service.get(r));} @PostMapping("/put") @PreAuthorize("@ss.hasPermission('amazon:listings-items:update')") public CommonResult<Map<String,Object>> put(@Valid @RequestBody AmazonListingsItemPutReqVO r){return CommonResult.success(service.put(r));} @PostMapping("/patch") @PreAuthorize("@ss.hasPermission('amazon:listings-items:update')") public CommonResult<Map<String,Object>> patch(@Valid @RequestBody AmazonListingsItemPatchReqVO r){return CommonResult.success(service.patch(r));} @PostMapping("/delete") @PreAuthorize("@ss.hasPermission('amazon:listings-items:update')") public CommonResult<Map<String,Object>> delete(@Valid @RequestBody AmazonListingsItemGetReqVO r){return CommonResult.success(service.delete(r));} }
